/// Display-unit conversion from a channel unit; identity when `from == to`.
pub fn conversion(from: &str, to: &str) -> Option<Conversion> {
    if from == to {
        return Some(Conversion::Scale(1.0));
    }
    match (from, to) {
        ("m/s", "mph") => Some(Conversion::Scale(2.2369362920544)),
        ("m/s", "km/h") => Some(Conversion::Scale(3.6)),
        ("rad", "deg") => Some(Conversion::Scale(57.29577951308232)),
        ("rad/s", "deg/s") => Some(Conversion::Scale(57.29577951308232)),
        ("m/s2", "g") => Some(Conversion::Scale(0.10197162129779283)),
        ("L", "US gal") => Some(Conversion::Scale(0.2641720524)),
        ("C", "F") => Some(Conversion::ScaleOffset { scale: 1.8, offset: 32.0 }),
        ("ratio", "%") => Some(Conversion::Scale(100.0)),
        _ => None,
    }
}

